import{_ as a}from"./chunks/emo.Cly4kUfc.js";import{_ as s}from"./chunks/home-estop.pc.ko.kEdjV6kh.js";import{_ as o,o as r,c as e,a5 as n}from"./chunks/framework.BjM_ivYE.js";const f=JSON.parse('{"title":"비상 정지 절차","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/safety/emergency-stop-procedures.md","filePath":"ko/manual/safety/emergency-stop-procedures.md","lastUpdated":1790653972000}'),i={name:"ko/manual/safety/emergency-stop-procedures.md"};function l(c,t,d,p,g,u){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="비상-정지-절차" tabindex="-1">비상 정지 절차 <a class="header-anchor" href="#비상-정지-절차" aria-label="Permalink to &quot;비상 정지 절차&quot;">​</a></h1><p>위험 상황에서 로봇을 즉시 멈추기 위한 비상 정지 사용 방법과 복구 절차입니다. 일상적인 비상 정지·복구 조작은 <a href="/RBQ/ko/manual/operation/emo.html">비상 정지 및 복구</a>에서도 확인할 수 있습니다.</p><h2 id="자동-정지·안전-관련-기능" tabindex="-1">자동 정지·안전 관련 기능 <a class="header-anchor" href="#자동-정지·안전-관련-기능" aria-label="Permalink to &quot;자동 정지·안전 관련 기능&quot;">​</a></h2><p>다음 상황에서는 로봇이 자동으로 멈추거나 모터 전원이 차단될 수 있습니다.</p><ul><li><strong>쓰러짐 감지</strong> 시</li><li><strong>배터리 부족</strong> 시</li><li><strong>컨트롤러(앱) 정지 명령</strong> 수신 시</li><li><strong>자동 미션 중 인터럽트</strong> 신호 수신 시</li></ul><p>RBQ에는 <strong>비상 정지(E-Stop)</strong>, <strong>원격 정지</strong>, <strong>이동 속도 제한</strong>, <strong>자세 안정 제어</strong> 등 안전 관련 기능이 있습니다. 평지에서 안전 관련 정지 시 <strong>정지 거리는 최대 약 1m</strong> 수준을 가정할 수 있으며, 경사나 불규칙한 바닥에서는 더 길어질 수 있습니다.</p><h2 id="비상-정지-버튼-사용" tabindex="-1">비상 정지 버튼 사용 <a class="header-anchor" href="#비상-정지-버튼-사용" aria-label="Permalink to &quot;비상 정지 버튼 사용&quot;">​</a></h2><figure><img src="'+a+'" alt="로봇 후면에 위치한 비상 정지 푸시 버튼"><figcaption style="text-align:center;">[ 로봇 후면에 위치한 비상 정지 푸시 버튼 ]</figcaption></figure><p>로봇 후면에 있는 <strong>비상 정지 푸시 버튼</strong>을 누르면, 모든 관절이 <strong>High Damping</strong> 상태로 전환됩니다. 이 상태에서는 로봇이 외부 힘에 저항하지만, 토크·위치 명령은 받지 않으며 제어가 비활성화되어 로봇이 바닥으로 주저앉을 수 있습니다.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>비상 정지는 사람과 로봇을 보호하기 위한 조치입니다. 이상 동작, 충돌 위험, 감전·끼임 위험이 있을 때 즉시 비상 정지 버튼을 누르세요. <strong>비상 정지는 일상적인 보호 수단이 아니라, 진짜 비상 상황에서만 사용</strong>하세요. 무분별한 사용은 제어 해제로 인한 안정성 상실로 추가 위험을 만들 수 있습니다.</p></div></div><h2 id="비상-정지-후-복구" tabindex="-1">비상 정지 후 복구 <a class="header-anchor" href="#비상-정지-후-복구" aria-label="Permalink to &quot;비상 정지 후 복구&quot;">​</a></h2><ol><li><strong>버튼 해제</strong>: 비상 정지 버튼을 시계 방향으로 돌려 원래 위치로 되돌립니다.</li><li><strong>자세 복구</strong>: 앱에서 <strong>자동 기동</strong>을 실행하거나, <a href="/RBQ/ko/manual/operation/initial-pose.html">로봇 초기 자세 설정</a>에 따라 초기 자세를 설정합니다.</li><li><strong>원인 확인</strong>: 비상 정지를 유발한 원인(장애물, 오류, 설정 오류 등)을 제거하거나 수정한 뒤 다시 운용하세요.</li></ol><h2 id="앱에서-정지" tabindex="-1">앱에서 정지 <a class="header-anchor" href="#앱에서-정지" aria-label="Permalink to &quot;앱에서 정지&quot;">​</a></h2><figure><img src="'+s+'" alt="앱 상단 바의 E-STOP 버튼과 확인 창"><figcaption style="text-align:center;">[ 상단 바 오른쪽의 <code>E-STOP</code> 과 확인 창 ]</figcaption></figure><p>빨간 <code>E-STOP</code> 버튼은 제어 홈에서는 상단 바 오른쪽에, 다른 화면에서는 헤더 오른쪽에 있습니다. 다만 로봇이 연결돼 있거나 끊긴 뒤 다시 붙는 동안(8초)에만 나옵니다. 연결되지 않은 상태에서는 버튼이 그려지지 않으므로, 그때는 위의 <strong>로봇 본체 물리 버튼</strong>을 쓰십시오. 누르면 확인 창이 열리고, <code>정지</code>를 눌러야 전송됩니다. 확인 없이 나가는 경로는 없습니다.</p><p>로봇 소유권이 없어도 됩니다 — 로봇은 연결된 어느 기기의 E-STOP 이든 받아들입니다. 자세한 동작은 <a href="/RBQ/ko/manual/gui/emergency.html">비상 정지</a>에 있습니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p><code>E-STOP</code> 을 누르면 모든 모터의 파워가 꺼져 <strong>로봇이 그 자리에 주저앉습니다.</strong> 위급한 상황에서만 사용하세요. 로봇이 응답하지 않으면 앱 로그에 <em>E-Stop 전송 실패 — 응답 없음. 물리 E-Stop을 사용하세요</em> 가 남습니다 — 기다리지 말고 물리 버튼을 누르세요.</p></div></div><h2 id="전원-차단-후-잔류-움직임" tabindex="-1">전원 차단 후 잔류 움직임 <a class="header-anchor" href="#전원-차단-후-잔류-움직임" aria-label="Permalink to &quot;전원 차단 후 잔류 움직임&quot;">​</a></h2><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>전원이 꺼져도 RBQ 다리는 <strong>자동으로 잠기지 않습니다.</strong> 경사면·계단·미끄러운 바닥에서는 전원 차단 후에도 미끄러짐·굴러감·관성에 의한 이동이 발생할 수 있으므로, 정지했다고 해서 즉시 완전히 안전한 상태가 되는 것은 아닙니다.</p></div></div><p>경사면·계단·미끄러운 바닥에서는 전원 차단 후에도 다음이 발생할 수 있습니다.</p><ul><li><strong>미끄러짐</strong></li><li><strong>굴러 떨어짐</strong></li><li><strong>관성에 의한 계속 이동</strong></li></ul><p>접근할 때는 바닥 조건과 자세를 확인한 뒤, 안전한 방향에서만 접근하세요.</p>',22)])])}const _=o(i,[["render",l]]);export{f as __pageData,_ as default};
